-- El juego de caracteres se fija SIEMPRE: el cliente mysql lo toma del entorno y en un
-- contenedor sin locale eso es latin1, que convierte cada tilde en mojibake sin dar error.
SET NAMES utf8mb4;

-- Fotos de puntos de interés (poi-images.js)
-- Cuatro Calas (4/4), Sierra Espuña (6/13) y Carrascoy y El Valle (8/21).
-- Wikimedia Commons, licencias CC BY / CC BY-SA / CC0. Idempotente: UPDATE por slug + park_id.
-- Las 4 de Cuatro Calas y 5 de las 8 de Carrascoy salen de Tools/catalogo-nacional/data/poi-foto.json
-- (archivo elegido a mano); las demás, de la cadena automática del script.
-- OJO: poi-images.js --park <slug> reescribe este fichero SOLO con las sentencias de ese espacio.
-- Las de los otros espacios se conservan aquí a mano porque ya están aplicadas contra la BD.
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Entrada_a_la_Cala_La_Carolina.jpg?width=1280', source = 'Inventario Español de Lugares de Interés Geológico (IELIG), IGME — LIG BE006 «Vulcanismo de La Carolina». La coordenada es la del propio punto del inventario; Wikimedia Commons (foto: Mabelcalabuig, CC BY-SA 3.0 es)' WHERE slug = 'vulcanismo-de-la-carolina' AND park_id = (SELECT id FROM parks WHERE slug = 'cuatro-calas');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Cala_Cerrada_o_de_los_Cocederos%2C_en_el_Paraje_Protegido_Las_Cuatro_Calas.JPG?width=1280', source = 'Posición: OpenStreetMap way/1459077450 (ODbL). Uso espartero documentado en Wikimedia Commons («Antiguo deposito de esparto en la Cala de los Cocederos», «Depositos excavados en el acantilado, Cala de los Cocederos»); pendiente de contrastar con fuente documental. El IELIG y Commons escriben «Cocederos»; OpenStreetMap, «Cocedores»; Wikimedia Commons (foto: Mabelcalabuig, CC BY-SA 3.0 es)' WHERE slug = 'playa-de-los-cocedores' AND park_id = (SELECT id FROM parks WHERE slug = 'cuatro-calas');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Cuatro_Calas_Murcia.jpg?width=1280', source = 'Inventario Español de Lugares de Interés Geológico (IELIG), IGME — LIG BE005, cuya denominación oficial es «Playa de Cuatro Calas»; aquí se le da otro nombre para no confundirlo con el del propio espacio protegido. approx: el punto del inventario representa el conjunto del tramo costero, no un afloramiento puntual; Wikimedia Commons (foto: Mynomadicbackpack, CC BY-SA 4.0)' WHERE slug = 'conglomerados-de-cuatro-calas' AND park_id = (SELECT id FROM parks WHERE slug = 'cuatro-calas');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Calarreona%2C_lado_sur%2C_en_Las_Cuatro_Calas.JPG?width=1280', source = 'Posición: OpenStreetMap (ODbL). Sendero SL-MU 18 homologado por la FMRM. Su recorrido no aparece dibujado en el mapa: el sendero está señalizado sobre el terreno, pero no cartografiado en OpenStreetMap, que es de donde sale la capa de senderos; Wikimedia Commons (foto: Mabelcalabuig, CC BY-SA 3.0 es)' WHERE slug = 'playa-de-calarreona' AND park_id = (SELECT id FROM parks WHERE slug = 'cuatro-calas');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Pozos_de_la_Nieve_de_Murcia_11-03-2024.jpg?width=1280', source = 'Bien de Interés Cultural, categoría Sitio de Interés Etnográfico (Dirección General de Bienes Culturales, Región de Murcia). Posición de los 28 pozos en OpenStreetMap (man_made=ice_house, ODbL). approx: la coordenada es la del Pozo 1 (node/8543844778) y representa el conjunto; Wikimedia Commons (foto: Lorenzo Soriano, CC BY 4.0)' WHERE slug = 'pozos-de-la-nieve' AND park_id = (SELECT id FROM parks WHERE slug = 'sierra-espuna');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Casa_Forestal_de_Huerta_Espu%C3%B1a._Sierra_Espu%C3%B1a.jpg?width=1280', source = 'OpenStreetMap way/900533315 (historic=yes, ODbL). Pendiente de contrastar con fuente documental; Wikimedia Commons (foto: Lorenzo Soriano, CC BY-SA 4.0)' WHERE slug = 'casa-forestal-de-huerta-espuna' AND park_id = (SELECT id FROM parks WHERE slug = 'sierra-espuna');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Centro_de_Visitantes_y_Gesti%C3%B3n_Ricardo_Codorniu._Sierra_Espu%C3%B1a.jpg?width=1280', source = 'OpenStreetMap way/170061146 (amenity=ranger_station, tourism=information, historic=house, ODbL); Wikimedia Commons (foto: Lorenzo Soriano, CC BY-SA 4.0)' WHERE slug = 'centro-de-visitantes-ricardo-codorniu' AND park_id = (SELECT id FROM parks WHERE slug = 'sierra-espuna');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Antiguo_Sanatorio_de_Tuberculosos_de_Sierra_Espu%C3%B1a_03.jpg?width=1280', source = 'OpenStreetMap way/132482920 (historic=building, building=hospital, ruins=yes, ODbL); denominación confirmada en Nominatim. Fechas de construcción y cierre pendientes de contrastar con fuente documental; Wikimedia Commons (foto: Jayma photography ltd, CC BY-SA 4.0)' WHERE slug = 'sanatorio-de-tuberculosos' AND park_id = (SELECT id FROM parks WHERE slug = 'sierra-espuna');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Restos_de_la_Torre_del_Azaraque_(Alhama_de_Murcia).jpg?width=1280', source = 'OpenStreetMap way/1097841454 (historic=ruins, man_made=tower, ODbL). Época y función pendientes de contrastar con fuente documental; Wikimedia Commons (foto: Lorenzo Soriano, CC BY-SA 4.0)' WHERE slug = 'torre-del-azaraque' AND park_id = (SELECT id FROM parks WHERE slug = 'sierra-espuna');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Iglesia_de_Santa_Eulalia_de_Merida_(1).jpg?width=1280', source = 'Decreto 96/2002, de 7 de junio, del Consejo de Gobierno de la Región de Murcia, por el que se declara bien de interés cultural, con categoría de monumento, la iglesia de Santa Eulalia de Mérida, en Totana. Posición: OpenStreetMap way/152263929 (ODbL); Wikimedia Commons (foto: Pedro J Pacheco, CC BY-SA 3.0 es)' WHERE slug = 'santuario-de-santa-eulalia' AND park_id = (SELECT id FROM parks WHERE slug = 'sierra-espuna');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Santuario_de_la_Fuensanta%2C_Murcia.JPG?width=1280', source = 'PORN del Parque Regional Carrascoy y El Valle (Orden de 18 de mayo de 2005, BORM n.º 129 de 07.06.2005), Memoria Descriptiva §1 y Normativa (subzona de uso público intensivo «Santuario de La Fuensanta»); declarado Bien de Interés Cultural el 22.06.1983 según OpenStreetMap y el registro estatal, sin contrastar en la fuente oficial (el registro del Ministerio de Cultura no responde desde este entorno). Coordenada: OpenStreetMap way/55846465 (ODbL); Wikimedia Commons (foto: José Garcia, "pepegar", CC BY-SA 3.0)' WHERE slug = 'santuario-de-la-fuensanta' AND park_id = (SELECT id FROM parks WHERE slug = 'carrascoy-y-el-valle');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Eremitorio_Nuestra_Se%C3%B1ora_de_la_Luz_in_Santo_%C3%81ngel%2C_Murcia%2C_Spain%2C_2020_January_-_2.jpg?width=1280', source = 'PORN del Parque Regional Carrascoy y El Valle (Orden de 18 de mayo de 2005, BORM n.º 129 de 07.06.2005), Memoria Descriptiva §3.3 (hitos paisajísticos) y §4.3.2. Coordenada: OpenStreetMap way/653754604 (ODbL); Wikimedia Commons (foto: Ximonic (Simo Räsänen), CC BY-SA 4.0)' WHERE slug = 'eremitorio-de-la-luz' AND park_id = (SELECT id FROM parks WHERE slug = 'carrascoy-y-el-valle');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Castillo_de_la_Asomada._El_Palmar_(Murcia).jpg?width=1280', source = 'PORN del Parque Regional Carrascoy y El Valle (Orden de 18 de mayo de 2005, BORM n.º 129 de 07.06.2005), Memoria Descriptiva §1, §3.3 (hito «Cabezo del Puerto») y §4.2.2.1 (monte 79 Bis, Trozo 2.º «Castillo del Puerto»); datación y descripción: Región de Murcia Digital (CARM), ficha del Castillo de la Asomada, que lo cataloga como Bien de Interés Cultural por la Disposición Adicional Segunda de la Ley 16/1985 del Patrimonio Histórico Español. Coordenada: OpenStreetMap node/10277995531, a 13 m de la de Wikidata Q24568061 (ODbL); Wikimedia Commons (foto: Laura Pérez Ibáñez, CC BY-SA 4.0)' WHERE slug = 'castillo-de-la-asomada' AND park_id = (SELECT id FROM parks WHERE slug = 'carrascoy-y-el-valle');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Crestadelgallo.JPG?width=1280', source = 'PORN del Parque Regional Carrascoy y El Valle (Orden de 18 de mayo de 2005, BORM n.º 129 de 07.06.2005), Memoria Descriptiva §3.3 y §4.2.7.2, y Normativa (subzona de uso público intensivo «Cresta del Gallo»). Coordenada: OpenStreetMap node/747347873 (ODbL); Wikimedia Commons (foto: Gregorico, CC BY-SA 4.0)' WHERE slug = 'cresta-del-gallo' AND park_id = (SELECT id FROM parks WHERE slug = 'carrascoy-y-el-valle');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Vistas_desde_el_Pico_Relojero.jpg?width=1280', source = 'PORN del Parque Regional Carrascoy y El Valle (Orden de 18 de mayo de 2005, BORM n.º 129 de 07.06.2005), Memoria Descriptiva §4.2.7.2 (miradores habilitados: «El Relojero (al pie del Relojero)»). Coordenada aproximada: el plan sitúa el mirador al pie del cerro y la coordenada es la de la torre de observación de la cima, OpenStreetMap way/136894912 (ODbL); Wikimedia Commons (foto: Juan Antonio Pellicer Alcaraz, CC BY-SA 3.0 es)' WHERE slug = 'mirador-del-relojero' AND park_id = (SELECT id FROM parks WHERE slug = 'carrascoy-y-el-valle');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Sierradecarrascoy.JPG?width=1280', source = 'PORN del Parque Regional Carrascoy y El Valle (Orden de 18 de mayo de 2005, BORM n.º 129 de 07.06.2005), Memoria Descriptiva §3.3 (hitos paisajísticos) y Normativa (zona de conservación prioritaria). Coordenada y altitud: OpenStreetMap node/26864606, que rotula la cumbre con el nombre de la sierra (ODbL); Wikimedia Commons (foto: Sapoproductions, CC BY-SA 4.0)' WHERE slug = 'cumbre-de-carrascoy' AND park_id = (SELECT id FROM parks WHERE slug = 'carrascoy-y-el-valle');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Panel_informativo_en_%C3%81rea_Recreativa_El_Valle_Perdido..jpg?width=1280', source = 'PORN del Parque Regional Carrascoy y El Valle (Orden de 18 de mayo de 2005, BORM n.º 129 de 07.06.2005), Memoria Descriptiva §4.2.7.2 y Normativa (subzona de uso público intensivo «Valle Perdido-El Sequén»). Coordenada: OpenStreetMap relation/1852332 (ODbL); Wikimedia Commons (foto: Juan Antonio Pellicer Alcaraz, CC BY-SA 3.0 es)' WHERE slug = 'area-recreativa-el-valle-perdido' AND park_id = (SELECT id FROM parks WHERE slug = 'carrascoy-y-el-valle');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Paisaje_Lunar_desde_Columbares.jpg?width=1280', source = 'PORN del Parque Regional Carrascoy y El Valle (Orden de 18 de mayo de 2005, BORM n.º 129 de 07.06.2005), Memoria Descriptiva §3.1.2.3 (Lugares de Interés Geológico: «Bad lands de la vertiente sur de la Sierra de la Cresta del Gallo (Paisaje lunar)», del inventario de El Patrimonio Geológico de la Región de Murcia, Fundación Séneca, 1999), §3.1.2.4 (regosoles margálicos) y §3.3 (hitos paisajísticos). Coordenada aproximada: ninguna fuente delimita el paraje —el PORN solo dice «al sur de la Cresta del Gallo»— y no tiene nodo en OpenStreetMap, así que se le da la del mirador de la Cresta del Gallo, que es el punto desde el que se observa; Wikimedia Commons (foto: Wadim, CC BY-SA 4.0)' WHERE slug = 'paisaje-lunar' AND park_id = (SELECT id FROM parks WHERE slug = 'carrascoy-y-el-valle');
